using SuperMetroid.Core.Assets;

internal static partial class Program
{
    // Independent pre-conversion strip order at22b928b4: native simple animation
    // operands, rightward treadmill operands, complete statue strip, then spores.
    // Metadata only, captured from supported ROM; never generated by Segments.
    private static RoomFxAtlasSegment[] OriginalRoomFxAtlasSegments() =>
    [
        new(0x8791e4, 0x0040, true),
        new(0x879224, 0x0040, true),
        new(0x879264, 0x0040, true),
        new(0x8792a4, 0x0040, true),
        new(0x879164, 0x0020, true),
        new(0x879184, 0x0020, true),
        new(0x8791a4, 0x0020, true),
        new(0x8791c4, 0x0020, true),
        new(0x87a564, 0x0040, true),
        new(0x87a5a4, 0x0040, true),
        new(0x87a5e4, 0x0040, true),
        new(0x87a624, 0x0040, true),
        new(0x87a664, 0x0040, true),
        new(0x87a6a4, 0x0040, true),
        new(0x87a6e4, 0x0040, true),
        new(0x87a724, 0x0040, true),
        new(0x87a764, 0x0040, true),
        new(0x87a7a4, 0x0040, true),
        new(0x87a874, 0x0050, true),
        new(0x87a8c4, 0x0050, true),
        new(0x87a914, 0x0050, true),
        new(0x87a964, 0x0050, true),
        new(0x87a9b4, 0x0050, true),
        new(0x878e64, 0x0020, true),
        new(0x878e84, 0x0020, true),
